#ifndef EXCELTOCSVCONVERTER_H
#define EXCELTOCSVCONVERTER_H

#include <QMainWindow>
#include <QString>

QT_BEGIN_NAMESPACE
class QPushButton;
class QLabel;
class QProgressBar;
class QTextEdit;
QT_END_NAMESPACE

class ExcelToCsvConverter : public QMainWindow
{
    Q_OBJECT

public:
    ExcelToCsvConverter(QWidget *parent = nullptr);

private slots:
    void selectDirectory();
    void convertFiles();
    void appendLog(const QString &message);

private:
    QPushButton *selectDirButton;
    QPushButton *convertButton;
    QLabel *selectedDirLabel;
    QProgressBar *progressBar;
    QTextEdit *logOutput;
    QString selectedDirectory;

    bool convertExcelToCsv(const QString &excelPath, const QString &csvPath);
    QStringList findExcelFiles(const QString &directory);
};

#endif // EXCELTOCSVCONVERTER_H
