**ExcelToCsvConverter.cpp**
```cpp
#include "ExcelToCsvConverter.h"
#include <QVBoxLayout>
#include <QPushButton>
#include <QLabel>
#include <QFileDialog>
#include <QProgressBar>
#include <QTextEdit>
#include <QDir>
#include <QFileInfo>
#include <QMessageBox>
#include <QAxObject>
#include <QVariant>
#include <QDebug>

ExcelToCsvConverter::ExcelToCsvConverter(QWidget *parent)
    : QMainWindow(parent)
{
    // Create central widget and layout
    QWidget *centralWidget = new QWidget(this);
    QVBoxLayout *layout = new QVBoxLayout(centralWidget);

    // Create widgets
    selectDirButton = new QPushButton("Select Directory", this);
    selectedDirLabel = new QLabel("No directory selected", this);
    convertButton = new QPushButton("Convert Excel Files to CSV", this);
    convertButton->setEnabled(false);
    progressBar = new QProgressBar(this);
    progressBar->setVisible(false);
    logOutput = new QTextEdit(this);
    logOutput->setReadOnly(true);

    // Add widgets to layout
    layout->addWidget(selectDirButton);
    layout->addWidget(selectedDirLabel);
    layout->addWidget(convertButton);
    layout->addWidget(progressBar);
    layout->addWidget(new QLabel("Conversion Log:"));
    layout->addWidget(logOutput);

    setCentralWidget(centralWidget);
    setWindowTitle("Excel to CSV Converter");
    resize(600, 400);

    // Connect signals
    connect(selectDirButton, &QPushButton::clicked, this, &ExcelToCsvConverter::selectDirectory);
    connect(convertButton, &QPushButton::clicked, this, &ExcelToCsvConverter::convertFiles);
}

void ExcelToCsvConverter::selectDirectory()
{
    QString dir = QFileDialog::getExistingDirectory(this, "Select Directory", 
                                                     QDir::homePath(),
                                                     QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);

    if (!dir.isEmpty()) {
        selectedDirectory = dir;
        selectedDirLabel->setText("Selected: " + dir);
        convertButton->setEnabled(true);
        logOutput->clear();
    }
}

void ExcelToCsvConverter::convertFiles()
{
    if (selectedDirectory.isEmpty()) {
        return;
    }

    logOutput->clear();
    appendLog("Starting conversion process...");

    // Find all Excel files
    QStringList excelFiles = findExcelFiles(selectedDirectory);

    if (excelFiles.isEmpty()) {
        appendLog("No Excel files found in the selected directory.");
        QMessageBox::information(this, "No Files", "No Excel files found in the selected directory.");
        return;
    }

    appendLog(QString("Found %1 Excel file(s)").arg(excelFiles.size()));

    // Create output directory
    QDir dir(selectedDirectory);
    QString outputDirName = "CSV_Output";
    if (!dir.exists(outputDirName)) {
        if (!dir.mkdir(outputDirName)) {
            appendLog("Error: Could not create output directory.");
            QMessageBox::critical(this, "Error", "Could not create output directory.");
            return;
        }
    }

    QString outputPath = dir.absoluteFilePath(outputDirName);
    appendLog("Output directory: " + outputPath);

    // Setup progress bar
    progressBar->setVisible(true);
    progressBar->setMaximum(excelFiles.size());
    progressBar->setValue(0);

    // Convert each file
    int successCount = 0;
    for (int i = 0; i < excelFiles.size(); ++i) {
        QString excelFile = excelFiles[i];
        QFileInfo fileInfo(excelFile);
        QString csvFileName = fileInfo.baseName() + ".csv";
        QString csvPath = QDir(outputPath).absoluteFilePath(csvFileName);

        appendLog(QString("Converting: %1").arg(fileInfo.fileName()));

        if (convertExcelToCsv(excelFile, csvPath)) {
            successCount++;
            appendLog(QString("  ✓ Successfully converted to: %1").arg(csvFileName));
        } else {
            appendLog(QString("  ✗ Failed to convert: %1").arg(fileInfo.fileName()));
        }

        progressBar->setValue(i + 1);
        QApplication::processEvents(); // Keep UI responsive
    }

    progressBar->setVisible(false);

    QString summary = QString("\nConversion complete!\nSuccessfully converted: %1/%2 files")
                          .arg(successCount).arg(excelFiles.size());
    appendLog(summary);

    QMessageBox::information(this, "Conversion Complete", summary);
}

QStringList ExcelToCsvConverter::findExcelFiles(const QString &directory)
{
    QDir dir(directory);
    QStringList filters;
    filters << "*.xlsx" << "*.xls" << "*.xlsm" << "*.xlsb";

    QStringList files = dir.entryList(filters, QDir::Files);
    QStringList fullPaths;

    for (const QString &file : files) {
        fullPaths << dir.absoluteFilePath(file);
    }

    return fullPaths;
}

bool ExcelToCsvConverter::convertExcelToCsv(const QString &excelPath, const QString &csvPath)
{
    QAxObject *excel = new QAxObject("Excel.Application", this);
    if (!excel) {
        delete excel;
        return false;
    }

    try {
        excel->setProperty("Visible", false);
        excel->setProperty("DisplayAlerts", false);

        QAxObject *workbooks = excel->querySubObject("Workbooks");
        QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", excelPath);

        if (!workbook) {
            excel->dynamicCall("Quit()");
            delete excel;
            return false;
        }

        // Get the first worksheet
        QAxObject *worksheets = workbook->querySubObject("Worksheets");
        QAxObject *worksheet = worksheets->querySubObject("Item(int)", 1);

        // Save as CSV (FileFormat=6 for CSV)
        worksheet->dynamicCall("SaveAs(const QString&, int)", csvPath, 6);

        workbook->dynamicCall("Close()");
        excel->dynamicCall("Quit()");

        delete excel;
        return true;

    } catch (...) {
        try {
            excel->dynamicCall("Quit()");
        } catch (...) {}
        delete excel;
        return false;
    }
}

void ExcelToCsvConverter::appendLog(const QString &message)
{
    logOutput->append(message);
    QApplication::processEvents();
}
